alter table public.setores add column if not exists ativo boolean not null default true;
create unique index if not exists setores_unidade_nome_unique on public.setores (unidade_id, lower(nome));
alter table public.checklist_templates add column if not exists responsavel_id uuid references public.usuarios(id) on delete set null;
create or replace function public.sou_gestor() returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.usuarios where id = auth.uid() and perfil = 'gestor'); $$;
create policy "gestor cria checklists da propria empresa" on public.checklist_templates for insert with check (unidade_id in (select id from public.unidades where empresa_id = public.empresa_atual()) and setor_id in (select id from public.setores where unidade_id = checklist_templates.unidade_id) and public.sou_gestor());
create policy "gestor edita checklists da propria empresa" on public.checklist_templates for update using (unidade_id in (select id from public.unidades where empresa_id = public.empresa_atual()) and public.sou_gestor()) with check (unidade_id in (select id from public.unidades where empresa_id = public.empresa_atual()) and setor_id in (select id from public.setores where unidade_id = checklist_templates.unidade_id));
create policy "gestor gerencia tarefas dos proprios checklists" on public.tarefa_templates for all using (checklist_template_id in (select id from public.checklist_templates where unidade_id in (select id from public.unidades where empresa_id = public.empresa_atual())) and public.sou_gestor()) with check (checklist_template_id in (select id from public.checklist_templates where unidade_id in (select id from public.unidades where empresa_id = public.empresa_atual())));